import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易尚氏學 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易尚氏學 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"classics/shangshi/062.md","filePath":"classics/shangshi/062.md"}'),s={name:"classics/shangshi/062.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>初四皆承陽。故曰巽。巽順也。順陽故小亨。往遇陽故利。陽居二五得中。故利見大人。</p><p>彖日。重巽以申命。剛巽乎中正而志行。柔皆順乎剛。是以小亨。利有攸往。利見大人。</p><p>巽為命令。虞書申命義叔。傳申重也。重巽以申命者。謂工者一再宣佈命令。以示鄭重也。巽為風。行莫疾於風。命令一齣。傳達天下。有若於風。故巽為命也。二五中正。下陰順承。故志行。</p><p>象曰。隨風。巽。君子以申命行事。</p><p>重巽故曰隨風。隨繼也。從也。言後風之隨前風也。令出惟行。萬事以治。故君子以之。</p><p>初六。進退。利武人之貞。</p><p>初臨重陽得主。故宜於進。而四無應與。故進而又退。象釋曰志疑。疑四無應也。震為武人。此巽卦也。何以利武人之佔。因震巽相反覆。巽究則為震。易貴將來。故武人利也。</p><h3 id="象曰。進退。志疑也。利武人之貞。志治也。" tabindex="-1">象曰。進退。志疑也。利武人之貞。志治也。 <a class="header-anchor" href="#象曰。進退。志疑也。利武人之貞。志治也。" aria-label="Permalink to “象曰。進退。志疑也。利武人之貞。志治也。”">​</a></h3><p>巽不果。故志疑。返震故志治。言得行其志以治天下。</p><p>九二。巽在床下。用史玉紛若。吉。無咎。</p><p>巽為床。初順二。故曰巽在床下。初至四正覆兌。兌口多。故曰用史巫紛若。按周禮內史雲。凡命諸侯孤卿大夫。則策命之。凡四方之事書。內史讀之。儀禮雲。辭多則史。又司巫雲。男巫女巫。凡邦之大栽。則歌哭而請。是史巫皆以口舌為用。而二居正反兌之間。故曰紛若。紛若言不一也。二得中故吉無咎。此義先儒無知者。只茹敦和雲。巽初之陰。伏於床下。震也。於是乎用史巫以祛之。史巫雲者互兌也。象始大明。而茹氏仍不知初至三為覆兌。故紛若不得解。</p><h3 id="象曰。紛若之吉。得中也。" tabindex="-1">象曰。紛若之吉。得中也。 <a class="header-anchor" href="#象曰。紛若之吉。得中也。" aria-label="Permalink to “象曰。紛若之吉。得中也。”">​</a></h3><p>二無應。失位。遇敵。然下孚於陰得中故吉。</p><p>九三。頻巽。吝。</p><p>王弼雲。頻。頻蹙不樂。按玉篇顰下雲。易本作頻。是頻即古文顰字。三居巽上。雖當位而下撓。故頻蹙不安而吝也。</p><h3 id="象曰。頻巽之吝。志窮也。" tabindex="-1">象曰。頻巽之吝。志窮也。 <a class="header-anchor" href="#象曰。頻巽之吝。志窮也。" aria-label="Permalink to “象曰。頻巽之吝。志窮也。”">​</a></h3><p>巽為心志。上無應。下乘陽。故曰志窮。</p><p>六四。悔亡。田獲三品。</p><p>當位承陽。故悔亡。伏震為田獵。兌羊離牛巽豕。故田獲三品。離卦數三也。凡陰遇重陽多吉。</p><h3 id="象曰。田獲三品。有功也。" tabindex="-1">象曰。田獲三品。有功也。 <a class="header-anchor" href="#象曰。田獲三品。有功也。" aria-label="Permalink to “象曰。田獲三品。有功也。”">​</a></h3><p>有所獲。故有功。</p><p>九五。貞吉。悔亡。無不利。無初有終。先庚三日。後度三日。吉。</p><p>九五得位。下孚於陰。故貞吉悔亡。巽為利。故無不利。震巽相反覆。無初者。言巽之初為震。震納庚。一爻當一日。故曰先庚三日。今震究為龔。故無初。有終者。言巽之究仍為震。終即後也。故曰後庚三日。以其終為震。故曰有終。震陽復故吉。先庚三日。言巽之先。後庚三日。言巽之究。與蠱之先甲三日。後甲三日義同。無初有終。與蠱之終則有始義亦同。</p><h3 id="象曰。九五之吉。位正中也。" tabindex="-1">象曰。九五之吉。位正中也。 <a class="header-anchor" href="#象曰。九五之吉。位正中也。" aria-label="Permalink to “象曰。九五之吉。位正中也。”">​</a></h3><p>九五既中且正。故吉。</p><p>上九。巽在床下。喪其資斧。貞兇。</p><p>巽順也。謂四。巽在床下。言順我者在下。上九失其輔助。故曰喪其資斧。斧輔通用。兌為斧亦為輔。上卦兌覆。故曰喪失也。說詳旅卦。</p><h3 id="象曰。巽在床下。上窮也。喪其資斧。正手兇也。" tabindex="-1">象曰。巽在床下。上窮也。喪其資斧。正手兇也。 <a class="header-anchor" href="#象曰。巽在床下。上窮也。喪其資斧。正手兇也。" aria-label="Permalink to “象曰。巽在床下。上窮也。喪其資斧。正手兇也。”">​</a></h3><p>九窮於上而下撓。故貞兇。象仍釋貞為正。其義不協。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
